 const x=a.number(1),y=a.number(2),z=a.number(3),inner=a.sourceArray([x,y]),input=a.sourceArray([inner,z]),out=a.invoke('nested',[input]);assert.deepEqual(read(a,out),js.nested([[1,2],3]));finish(a,[x,y,z,inner,input,out]);
