async function buildGenerations(){
 const files=(await readdir('bootstrap/compiler')).filter(file=>file.endsWith('.eli')).sort(),all=[b];let previous=b;
 for(const generation of[2,3]){const output=resolve(directory,'g'+generation),bootstrap=resolve(output,'bootstrap');await mkdir(bootstrap,{recursive:true});for(const file of files){const path=resolve('bootstrap/compiler',file),name=file.replace(/\.eli$/,'.mjs'),emission=previous.compiler.compile_string_with_source_map(await readFile(path,'utf8'),path,name,relative(bootstrap,path));await writeFile(resolve(bootstrap,name),emission.javascript+'//# sourceMappingURL='+name+'.map\n');await writeFile(resolve(bootstrap,name+'.map'),emission.sourceMap);}const current=await buildBackends({outputRoot:output,frontend:previous.compiler});current.compiler=await import(pathToFileURL(resolve(bootstrap,'compiler.mjs')).href);all.push(current);previous=current;}
 const filename=resolve('tests/fixtures/wasm-managed-catch-destructuring.eli'),source=await readFile(filename,'utf8'),seedFile=resolve(directory,'catch-binding-seed.mjs'),seed=spawnSync(resolve('bin/eliscript-seed'),['--output',seedFile,filename],{encoding:'utf8',timeout:30000});assert.equal(seed.status,0,seed.stderr);const javascript=await readFile(seedFile,'utf8'),outputs=[];
 for(const current of all){const p=current.compiler.compile_ir_string(source,filename),r=current.compiler.compile_ir_string(await readFile('bootstrap/runtime/memory.eli','utf8'),'runtime.eli');assert.equal(current.compiler.emit_ir_string(p),javascript);outputs.push(Uint8Array.from(current.managed.emit_managed_wasm(p,r)));}for(const file of files){const path=resolve('bootstrap/compiler',file),source=await readFile(path,'utf8'),expected=all[0].compiler.compile_string(source,path);for(const current of all.slice(1))assert.equal(current.compiler.compile_string(source,path),expected);}assert.deepEqual(outputs[0],outputs[1]);assert.deepEqual(outputs[1],outputs[2]);
 const seeded=await buildBackends({outputRoot:resolve(directory,'seed-backends'),seed:true}),p=seeded.compiler.compile_ir_string(source,filename),r=seeded.compiler.compile_ir_string(await readFile('bootstrap/runtime/memory.eli','utf8'),'runtime.eli');assert.deepEqual(Uint8Array.from(seeded.managed.emit_managed_wasm(p,r)),outputs[0]);return{bytes:outputs[2],javascript};
}
